{
  "items": [
    {
      "name": "Real.strictMonoOn_logb",
      "module_name": "Mathlib.Analysis.SpecialFunctions.Log.Base",
      "kind": "theorem",
      "type": "∀ {b : ℝ}, 1 < b → StrictMonoOn (Real.logb b) (Set.Ioi 0)"
    },
    {
      "name": "Real.logb_lt_logb",
      "module_name": "Mathlib.Analysis.SpecialFunctions.Log.Base",
      "kind": "theorem",
      "type": "∀ {b x y : ℝ}, 1 < b → 0 < x → x < y → Real.logb b x < Real.logb b y"
    },
    {
      "name": "ENNReal.log_lt_log",
      "module_name": "Mathlib.Analysis.SpecialFunctions.Log.ENNRealLog",
      "kind": "theorem",
      "type": "∀ {x y : ENNReal}, x < y → x.log < y.log"
    },
    {
      "name": "ENNReal.log_strictMono",
      "module_name": "Mathlib.Analysis.SpecialFunctions.Log.ENNRealLog",
      "kind": "theorem",
      "type": "StrictMono ENNReal.log"
    },
    {
      "name": "Real.log_lt_log",
      "module_name": "Mathlib.Analysis.SpecialFunctions.Log.Basic",
      "kind": "theorem",
      "type": "∀ {x y : ℝ}, 0 < x → x < y → Real.log x < Real.log y"
    },
    {
      "name": "Real.log_lt_log_iff",
      "module_name": "Mathlib.Analysis.SpecialFunctions.Log.Basic",
      "kind": "theorem",
      "type": "∀ {x y : ℝ}, 0 < x → 0 < y → (Real.log x < Real.log y ↔ x < y)"
    },
    {
      "name": "Real.strictMonoOn_log",
      "module_name": "Mathlib.Analysis.SpecialFunctions.Log.Basic",
      "kind": "theorem",
      "type": "StrictMonoOn Real.log (Set.Ioi 0)"
    },
    {
      "name": "Real.log_le_log_iff",
      "module_name": "Mathlib.Analysis.SpecialFunctions.Log.Basic",
      "kind": "theorem",
      "type": "∀ {x y : ℝ}, 0 < x → 0 < y → (Real.log x ≤ Real.log y ↔ x ≤ y)"
    }
  ]
}
